from collections.abc import Mapping


def make_web_config(environment=None, values=None):
    if environment is None:
        environment = "development"
    if environment not in {"development", "testing", "production"}:
        raise ValueError("unsupported environment")
    if values is None:
        values = {}
    if not isinstance(values, Mapping):
        raise TypeError("values must be a mapping or None")
    if any(not isinstance(key, str) for key in values):
        raise TypeError("configuration keys must be strings")

    database_url = values.get("DATABASE_URL")
    if not isinstance(database_url, str) or not database_url.strip():
        raise EnvironmentError("DATABASE_URL is required")

    raw_hosts = values.get("ALLOWED_HOSTS", "")
    if not isinstance(raw_hosts, str):
        raise TypeError("ALLOWED_HOSTS must be a string")
    hosts = []
    seen = set()
    for raw_host in raw_hosts.split(","):
        host = raw_host.strip()
        if host and host not in seen:
            seen.add(host)
            hosts.append(host)

    return {
        "ENVIRONMENT": environment,
        "DEBUG": environment == "development",
        "DATABASE_URL": database_url,
        "ALLOWED_HOSTS": tuple(hosts),
    }

