import unittest
from collections import UserDict

from solution import make_web_config


class MakeWebConfigTests(unittest.TestCase):
    def test_defaults_hosts_and_exact_output(self):
        values = {
            "DATABASE_URL": "postgres://db",
            "ALLOWED_HOSTS": " example.com,api.example.com, example.com, ,localhost ",
            "IGNORED": {"nested": []},
        }
        result = make_web_config(values=values)
        self.assertEqual(
            result,
            {
                "ENVIRONMENT": "development",
                "DEBUG": True,
                "DATABASE_URL": "postgres://db",
                "ALLOWED_HOSTS": ("example.com", "api.example.com", "localhost"),
            },
        )
        self.assertEqual(set(result), {"ENVIRONMENT", "DEBUG", "DATABASE_URL", "ALLOWED_HOSTS"})

    def test_all_environments_and_mapping_input(self):
        values = UserDict({"DATABASE_URL": " db ", "ALLOWED_HOSTS": ""})
        self.assertTrue(make_web_config("development", values)["DEBUG"])
        self.assertTrue(make_web_config("testing", values)["DEBUG"])
        production = make_web_config("production", values)
        self.assertFalse(production["DEBUG"])
        self.assertEqual(production["DATABASE_URL"], " db ")
        self.assertEqual(production["ALLOWED_HOSTS"], ())

    def test_environment_validation(self):
        for environment in ("dev", "Production", "", 1, True):
            with self.subTest(environment=environment):
                with self.assertRaises(ValueError):
                    make_web_config(environment, {"DATABASE_URL": "x"})

    def test_values_and_key_validation(self):
        for values in ([], (), "DATABASE_URL=x", 3):
            with self.subTest(values=values):
                with self.assertRaises(TypeError):
                    make_web_config(values=values)
        with self.assertRaises(TypeError):
            make_web_config(values={"DATABASE_URL": "x", 1: "ignored"})

    def test_database_url_is_mandatory_string(self):
        for values in (None, {}, {"DATABASE_URL": ""}, {"DATABASE_URL": None}, {"DATABASE_URL": True}, {"DATABASE_URL": 12}):
            with self.subTest(values=values):
                with self.assertRaisesRegex(EnvironmentError, "^DATABASE_URL is required$"):
                    make_web_config(values=values)

    def test_allowed_hosts_must_be_string_when_present(self):
        for hosts in (None, True, 3, ["host"]):
            with self.subTest(hosts=hosts):
                with self.assertRaises(TypeError):
                    make_web_config(values={"DATABASE_URL": "x", "ALLOWED_HOSTS": hosts})

    def test_input_is_not_mutated_or_aliased(self):
        values = {"DATABASE_URL": "x", "ALLOWED_HOSTS": "a,b", "OTHER": [1]}
        snapshot = {"DATABASE_URL": "x", "ALLOWED_HOSTS": "a,b", "OTHER": [1]}
        result = make_web_config(values=values)
        self.assertEqual(values, snapshot)
        result["DATABASE_URL"] = "changed"
        result["ALLOWED_HOSTS"] = ("changed",)
        self.assertEqual(values, snapshot)


if __name__ == "__main__":
    unittest.main()

